import { Node3D, Camera3D, Color, Environment, WorldEnvironment, DirectionalLight3D, Vector3, RenderingServer, OS } from "godot";
import { GameWorld } from "./game_world";
import { SoldierView } from "./client/soldier_view";
import { loadWeaponModel } from "./weapon_model_loader";
import type Game from "./game";
import type { SystemAdminSnapshot } from "../packages/game-rules/src/net/snapshot";

/** Temporary isolated capture stage: production body, rig, gun fitting and role materials. */
export default class ConceptCapture extends Node3D {
    private view!: SoldierView;
    godot_cli_action(request: string): string {
        if (!OS.is_debug_build()) return JSON.stringify({ accepted: false });
        const action = JSON.parse(request);
        const output = action.payload?.output;
        if (action.name !== "capture" || typeof output !== "string" || !output.endsWith(".png") || !/^[A-Za-z]:[\\/]/.test(output)) return JSON.stringify({ accepted: false });
        RenderingServer.force_draw(false, 0);
        const image = this.get_viewport()?.get_texture()?.get_image();
        if (!image) return JSON.stringify({ accepted: false, error: "viewport unavailable" });
        const error = image.save_png(output);
        return JSON.stringify({ accepted: error === 0, output, error });
    }
    _ready(): void {
        const kind = this.get_meta("kind", "pistol") as "pistol" | "cloaker";
        const environment = new Environment();
        environment.background_mode = Environment.BGMode.BG_COLOR;
        environment.background_color = new Color(0.65, 0.68, 0.72, 1);
        environment.ambient_light_source = Environment.AmbientSource.AMBIENT_SOURCE_COLOR;
        environment.ambient_light_color = new Color(0.85, 0.9, 1, 1);
        environment.ambient_light_energy = 0.8;
        const worldEnvironment = new WorldEnvironment();
        worldEnvironment.environment = environment;
        this.add_child(worldEnvironment);
        const light = new DirectionalLight3D();
        light.rotation_degrees = new Vector3(-30, -30, 0);
        light.light_energy = 1.5;
        this.add_child(light);
        const camera = new Camera3D();
        camera.projection = Camera3D.ProjectionType.PROJECTION_ORTHOGONAL;
        camera.size = 2.35;
        camera.position = new Vector3(1.9, 1.15, 5);
        this.add_child(camera);
        camera.look_at(new Vector3(0, 0.95, 0));
        camera.current = true;
        const world = new GameWorld(this, "model_showcase", true);
        const admin: SystemAdminSnapshot = { id: "soldier-concept", level: "soldier", weapon: kind, position: [0, 0.85, 0], targetId: null, lastAttackAtMs: 0, health: 100, maxHealth: 100, markedUntilMs: 10000, laggedUntilMs: 0, leakUntilMs: 0, lastShotHit: false, attackPhase: "none", attackPhaseStartedAtMs: 0, flinchUntilMs: 0, shieldHealth: 0 };
        world.syncSystemAdmins([admin], 1000, true);
        const actor = world.systemAdmin(admin.id)!;
        actor.body.position = new Vector3(0, 0.85, 0);
        actor.visual!.setAnimation(kind === "pistol" ? "PistolIdle" : "Idle");
        actor.visual!.animationPlayer!.seek(0.25, true);
        actor.visual!.animationPlayer!.pause();
        if (kind === "pistol") loadWeaponModel("pistol");
        Object.assign(this, { world, localPeerId: -1, camera, audio: null, streakRide: null, latestSnapshot: { systemAdmins: [admin], players: [], serverTimeMs: 1000 }, adminInterpolation: { renderedMotion: () => null } });
        this.view = new SoldierView(this as unknown as Game);
        this.view.update();
        this.set_meta("godot_cli_state", JSON.stringify({ kind, source: kind === "pistol" ? "character-marksman.glb" : "character-breach.glb", capture: "production renderer in isolated review stage", cloaker: "marked/revealed to inspect existing body" }));
    }
    _process(): void { this.view?.update(); }
}
